#include <iostream>
#include <mutex>
#include <thread>

int main() {
    int total{0};
    std::mutex mutex;
    auto worker = [&] {
        for (int i{0}; i < 20; ++i) {
            std::lock_guard<std::mutex> guard(mutex);
            ++total;
        }
    };
    std::thread a(worker), b(worker);
    a.join();
    b.join();
    std::cout << total << "\n";
}

